#include <stdio.h>
#include "../src/gbulletmesh89.h"

#define DEMO_MAX_V 512
#define DEMO_MAX_T 1024

static GBM_Vertex demo_v[DEMO_MAX_V];
static GBM_Tri demo_t[DEMO_MAX_T];

static void write_fix(FILE *f, gbm_fix x)
{
    long sign;
    long whole;
    long frac;
    if (x < 0L) {
        sign = 1L;
        x = -x;
    } else {
        sign = 0L;
    }
    whole = x / GBM_FIX_ONE;
    frac = ((x % GBM_FIX_ONE) * 10000L) / GBM_FIX_ONE;
    if (sign) fprintf(f, "-");
    fprintf(f, "%ld.%04ld", whole, frac);
}

static int write_obj(const char *path, const GBM_Mesh *m)
{
    FILE *f;
    unsigned short i;
    f = fopen(path, "w");
    if (f == 0) return 1;
    fprintf(f, "# generated by gbulletmesh89 demo\n");
    for (i = 0; i < m->v_count; ++i) {
        fprintf(f, "v ");
        write_fix(f, m->v[i].x);
        fprintf(f, " ");
        write_fix(f, m->v[i].y);
        fprintf(f, " ");
        write_fix(f, m->v[i].z);
        fprintf(f, " %u %u %u\n", (unsigned int)m->v[i].r, (unsigned int)m->v[i].g, (unsigned int)m->v[i].b);
    }
    for (i = 0; i < m->t_count; ++i) {
        fprintf(f, "f %u %u %u\n", (unsigned int)m->t[i].a + 1U, (unsigned int)m->t[i].b + 1U, (unsigned int)m->t[i].c + 1U);
    }
    fclose(f);
    return 0;
}

static void run_case(int ammo_type, const char *name)
{
    GBM_Mesh m;
    char path[160];
    gbm_mesh_init(&m, demo_v, DEMO_MAX_V, demo_t, DEMO_MAX_T);

    gbm_build_shell(&m, ammo_type);
    sprintf(path, "obj/%s_shell.obj", name);
    write_obj(path, &m);
    printf("%s shell: v=%u tri=%u err=%d\n", name, (unsigned int)m.v_count, (unsigned int)m.t_count, m.error);

    gbm_build_projectile(&m, ammo_type);
    sprintf(path, "obj/%s_projectile.obj", name);
    write_obj(path, &m);
    printf("%s projectile: v=%u tri=%u err=%d\n", name, (unsigned int)m.v_count, (unsigned int)m.t_count, m.error);

    gbm_build_full_round(&m, ammo_type);
    sprintf(path, "obj/%s_full_round.obj", name);
    write_obj(path, &m);
    printf("%s full: v=%u tri=%u err=%d\n", name, (unsigned int)m.v_count, (unsigned int)m.t_count, m.error);
}

int main(void)
{
    run_case(GBM_AMMO_PISTOL, "pistol");
    run_case(GBM_AMMO_SHOTGUN, "shotgun");
    run_case(GBM_AMMO_SNIPER, "sniper");
    run_case(GBM_AMMO_MAGNUM, "magnum");
    run_case(GBM_AMMO_MACHINEGUN, "machinegun");
    return 0;
}
